import sys, pathlib, threading, uuid
sys.path.insert(0,str(pathlib.Path('tests/.python-deps').resolve()))
import psycopg
ADMIN_DSN='host=127.0.0.1 port=55439 user=side_test dbname=postgres'
name='side_identity_'+uuid.uuid4().hex[:12]
with psycopg.connect(ADMIN_DSN,autocommit=True) as admin:
 admin.execute(psycopg.sql.SQL('CREATE DATABASE {}').format(psycopg.sql.Identifier(name)))
DSN=f'host=127.0.0.1 port=55439 user=side_test dbname={name}'
setup=r'''
do $$begin if not exists(select 1 from pg_roles where rolname='anon') then create role anon; end if; if not exists(select 1 from pg_roles where rolname='authenticated') then create role authenticated; end if; end$$; create schema auth; create schema extensions;
create table auth.users(id uuid primary key);
create function auth.uid() returns uuid language sql stable as $$select nullif(current_setting('test.uid',true),'')::uuid$$;
create function auth.role() returns text language sql stable as $$select current_setting('test.role',true)$$;
create extension pgcrypto with schema extensions;
create table public.empresas(id bigint generated by default as identity primary key);
create table public.partidas(id uuid primary key, codigo text, profesor_id uuid);
create table public.participantes(id uuid primary key default gen_random_uuid(),partida_id uuid,empresa_id bigint,nombre_legal_ingreso text,nombre_comercial_ingreso text,expulsada_at timestamptz);
create table public.side_student_state(empresa_id bigint primary key,snapshot jsonb);
create function public.side_normalizar_codigo_sala(text) returns text language sql immutable as $$select upper($1)$$;
create function public.side_normalizar_ingreso(text) returns text language sql immutable as $$select lower(trim($1))$$;
create function public.side_limpiar_whitespace_ingreso(text) returns text language sql immutable as $$select trim($1)$$;
create function public.side_respuesta_ingreso(uuid,boolean) returns jsonb language sql security definer as $$select jsonb_build_object('success',true,'empresa_id',empresa_id) from public.participantes where id=$1$$;
create function public.ingresar_empresa(text,text,text) returns jsonb language plpgsql security definer as $$declare eid bigint; pid uuid; gid uuid; begin select id into gid from public.partidas where codigo=$1;insert into public.empresas default values returning id into eid;insert into public.participantes(partida_id,empresa_id,nombre_legal_ingreso,nombre_comercial_ingreso) values(gid,eid,$2,$3) returning id into pid;return public.side_respuesta_ingreso(pid,false);end$$;
create function public.unirse_partida_por_codigo(text,text,text) returns jsonb language sql as $$select '{}'::jsonb$$;
create function public.obtener_estado_estudiante(p_codigo text,p_nombre_legal text,p_nombre_comercial text) returns jsonb language sql as $$select '{}'::jsonb$$;
create function public.guardar_estado_estudiante(p_codigo text,p_nombre_legal text,p_nombre_comercial text,p_snapshot jsonb,p_expected_revision bigint) returns jsonb language sql as $$select '{}'::jsonb$$;
create function public.guardar_decisiones_estudiante(p_codigo text,p_nombre_legal text,p_nombre_comercial text,p_ciclo integer,p_decisiones jsonb,p_expected_revision bigint) returns jsonb language sql as $$select '{}'::jsonb$$;
create function public.guardar_reporte_estudiante(text,text,text,integer,jsonb,bigint) returns jsonb language sql as $$select '{}'::jsonb$$;
create function public.side_podio_estudiante(p_codigo text,p_nombre_legal text,p_nombre_comercial text) returns jsonb language sql as $$select '{}'::jsonb$$;
grant execute on function public.obtener_estado_estudiante(text,text,text), public.guardar_estado_estudiante(text,text,text,jsonb,bigint), public.guardar_decisiones_estudiante(text,text,text,integer,jsonb,bigint), public.guardar_reporte_estudiante(text,text,text,integer,jsonb,bigint), public.side_podio_estudiante(text,text,text) to authenticated;
insert into auth.users values('11111111-1111-1111-1111-111111111111'),('22222222-2222-2222-2222-222222222222'),('33333333-3333-3333-3333-333333333333');
insert into public.partidas values('aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa','SIDE-TEST','33333333-3333-3333-3333-333333333333');
insert into public.empresas default values;
insert into public.participantes(partida_id,empresa_id,nombre_legal_ingreso,nombre_comercial_ingreso) values('aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa',1,'legal','marca');
'''
with psycopg.connect(DSN,autocommit=True) as c:
 c.execute(setup);c.execute(pathlib.Path('supabase/migrations/20261028151956_identidad_estudiante.sql').read_text(encoding='utf-8-sig'))
 c.execute('grant usage on schema auth to authenticated');c.execute('grant execute on function auth.uid() to authenticated');assert not c.execute("select has_table_privilege('authenticated','side_private.student_claims','select')").fetchone()[0]
results=[]; bar=threading.Barrier(2)
def claim(uid):
 with psycopg.connect(DSN) as c:
  c.execute("select set_config('test.uid',%s,false),set_config('test.role','authenticated',false)",[uid]);c.execute('set role authenticated');bar.wait();
  r=c.execute("select public.side_ingresar_empresa_segura('SIDE-TEST','legal','marca',null)").fetchone()[0];c.commit();results.append((uid,r))
a='11111111-1111-1111-1111-111111111111';b='22222222-2222-2222-2222-222222222222'
threads=[threading.Thread(target=claim,args=(u,)) for u in (a,b)]
for t in threads:t.start()
for t in threads:t.join()
assert len(results)==2,results
winners=[x for x in results if x[1].get('success')];losers=[x for x in results if x[1].get('code')=='CLAVE_REQUERIDA'];assert len(winners)==len(losers)==1,results
key=winners[0][1]['clave_empresa'];assert len(key)==8
with psycopg.connect(DSN) as c:
 c.execute("select set_config('test.uid',%s,false),set_config('test.role','authenticated',false)",[losers[0][0]]);c.execute('set role authenticated')
 assert c.execute("select public.obtener_estado_estudiante('SIDE-TEST','legal','marca')").fetchone()[0]['success'] is False
 assert c.execute("select public.guardar_estado_estudiante('SIDE-TEST','legal','marca','{}',0)").fetchone()[0]['success'] is False
 assert c.execute("select public.side_ingresar_empresa_segura('SIDE-TEST','legal','marca',%s)",[key]).fetchone()[0]['success'] is True
 c.commit()
 try:c.execute("select public.guardar_reporte_estudiante('SIDE-TEST','legal','marca',1,'{}',0)");raise AssertionError('client write allowed')
 except psycopg.errors.InsufficientPrivilege: c.rollback()
with psycopg.connect(DSN) as c:
 c.execute("select set_config('test.uid',%s,false),set_config('test.role','authenticated',false)",[winners[0][0]]);c.execute('set role authenticated')
 second=c.execute("select public.side_ingresar_empresa_segura('SIDE-TEST','legal2','marca2',null)").fetchone()[0];assert second['success'] is True
 assert c.execute("select public.obtener_estado_estudiante('SIDE-TEST','legal','marca')").fetchone()[0]['success'] is False
 assert c.execute("select public.side_liberar_empresa('aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa',1)").fetchone()[0]['success'] is False
 c.execute("select set_config('test.uid','',false)")
 assert c.execute("select public.side_ingresar_empresa_segura('SIDE-TEST','legal','marca',null)").fetchone()[0]['code']=='SESION_REQUERIDA'
 c.execute("select set_config('test.uid','33333333-3333-3333-3333-333333333333',false)")
 assert c.execute("select public.side_liberar_empresa('aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa',1)").fetchone()[0]['success'] is True
print('PASS PostgreSQL 17: dos empresas, reclamo simultáneo único, reingreso con clave, acceso ajeno, docente ajeno y escritura de reporte denegados. Fixture simplificado; no prueba el esquema completo ni Supabase Auth real.')
